<div class="section-head"><div><h2>Profile & settings</h2><p class="muted">Manage your public details and account password.</p></div></div><section class="grid grid-2"><form class="card form-grid" method="post" action="<?=e(url('/profile'))?>"><?=csrf_field()?><h2 class="field-full">Profile</h2><div class="field field-full"><label for="user_name">Name</label><input id="user_name" name="user_name" value="<?=e($profile['user_name'])?>" required></div><div class="field field-full"><label for="email">Email</label><input id="email" value="<?=e($profile['email'])?>" disabled><span class="help">Email changes require administrator verification.</span></div><div class="field field-full"><label for="institution">Institution</label><input id="institution" name="institution" value="<?=e($profile['institution']??'')?>"></div><div class="field-full"><span class="badge badge-active"><?=e($profile['account_status'])?></span> <span class="muted">Rating <?=e($profile['rating'])?> · <?=e(implode(', ',$profile['roles']))?></span></div><button class="button field-full">Save profile</button></form>
<form class="card grid" method="post" action="<?=e(url('/profile/password'))?>"><?=csrf_field()?><h2>Change password</h2><div class="field"><label for="current_password">Current password</label><input id="current_password" name="current_password" type="password" required></div><div class="field"><label for="password">New password</label><input id="password" name="password" type="password" minlength="10" required></div><div class="field"><label for="password_confirmation">Confirm password</label><input id="password_confirmation" name="password_confirmation" type="password" required></div><button class="button">Change password</button></form></section>
